package com.cryptox.util; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Component public class JwtUtil{ @Value("${app.jwt.secret}") String secret; @Value("${app.jwt.expiration-ms}") long exp; SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(String u){var n=new Date();return Jwts.builder().subject(u).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(key()).compact();}}